def build():
    catalog=[]
    for level,(level_name,signature,cases,tasks) in enumerate(LEVELS,1):
        params=signature.split(', ')
        for num,(title,body) in enumerate(tasks,1):
            eid=f"L{level:02d}-E{num:03d}"; fn=re.sub(r'[^a-z0-9]+','_',title.lower()).strip('_')
            exercise_cases=cases
            if level==9 and num==9:
                exercise_cases=[([(1,2),(3,3)],), ([(0,1),(2,4)],)]
            if level==3 and num==14:
                exercise_cases=[([[1,2],[3]],), ([],), ([[4]],)]
            imports='import math\n' if 'math.' in body else ''
            solution=f"{imports}def {fn}({signature}):\n    {body}\n"
            namespace={}; exec(solution,namespace)
            tests=[]
            for args in exercise_cases:
                try: expected=namespace[fn](*args)
                except (ValueError, ZeroDivisionError, TypeError): continue
                tests.append({'args':list(args),'expected':expected,'tolerance':1e-8})
            if not tests:
                raise ValueError(f'{eid} has no executable grading cases')
            th_title=TH_TITLES[level-1][num-1]
            ex={'id':eid,'level':level,'level_title':level_name,'title':th_title,'difficulty':['เริ่มต้น','เริ่มต้น','ปานกลาง','ปานกลาง','ปานกลาง','ท้าทาย','ท้าทาย','ท้าทาย','ท้าทาย','ท้าทาย'][level-1],'category':['เขียนโค้ด','ทำนายผล','แก้บั๊ก','เติมโค้ด','โจทย์ประยุกต์'][(num-1)%5],'objective':f'ฝึกเรื่อง{th_title} โดยเขียนฟังก์ชันให้ตรงตามสัญญา input/output','prerequisites':[] if eid=='L01-E001' else ([f'L{level:02d}-E{num-1:03d}'] if num>1 else [f'L{level-1:02d}-E015']),'function':fn,'signature':signature,'problem':f'เขียนฟังก์ชัน `{fn}({signature})` ให้ทำงานเรื่อง{th_title} ตามนิยามในบทเรียน ให้คืนค่าด้วย `return` ห้ามใช้ `print` แทนค่าผลลัพธ์ ตรวจตัวอย่างและกรณีขอบในชุดทดสอบ','sample':repr(exercise_cases[0]),'expected':repr(tests[0]['expected']) if tests else 'ดูผลในตัวอย่าง','constraints':'ใช้ Python 3.12 และ standard library; ห้ามแก้ tests, curriculum หรือไฟล์เฉลย; ตัวอย่างการเทรดเป็น paper-only','lesson':f'{th_title}: รับข้อมูลผ่าน parameters แล้วประมวลผลตามกติกา ฟังก์ชันคืนผลด้วย `return` เพื่อให้โปรแกรมส่วนอื่นและ grader ตรวจค่าได้ การคืนค่าและการพิมพ์ข้อความเป็นคนละอย่าง','example':'def identity(value):\n    return value\n\nassert identity(3) == 3','pitfall':'ตรวจกรณีข้อมูลว่าง ศูนย์ และขอบเขต; อย่าใช้ print แทน return','hints':[f'แยกให้ออกว่า input แต่ละตัวแทนอะไรในโจทย์เรื่อง{th_title}',f'ทำตามนิยามทีละขั้น แล้วค่อยจัดการกรณีว่างหรือศูนย์',f'ใช้ signature ที่ให้มา และตรวจชนิด/รูปแบบของค่าที่ return'],'lesson_file':f'lessons/{eid}.md','cases':tests,'assessment':num==15}
            catalog.append(ex)
            d=f'level_{level:02d}'
            (ROOT/'exercises'/d).mkdir(parents=True,exist_ok=True); (ROOT/'solutions'/d).mkdir(parents=True,exist_ok=True)
            (ROOT/'exercises'/d/f'{eid}.py').write_text(f'def {fn}({signature}):\n    """TODO: implement the behavior in the exercise instructions."""\n    raise NotImplementedError("เขียนฟังก์ชันนี้")\n',encoding='utf-8')
            (ROOT/'solutions'/d/f'{eid}.py').write_text(solution,encoding='utf-8')
            (ROOT/'explanations').mkdir(exist_ok=True)
            explanation=f"# {eid} — {th_title}\n\nฟังก์ชัน `{fn}` รับ `{signature}` แล้วคืนค่าตามกติกาในโจทย์\n\nอัลกอริทึม: `{body}`\n\nPython จะคำนวณ expression ทางขวาของ `return` แล้วส่งค่านั้นกลับไปยังผู้เรียก การใช้ `return` ทำให้ตรวจค่าได้โดยไม่ต้องอ่าน stdout\n\nข้อผิดพลาดที่พบบ่อย: ลืมกรณีข้อมูลว่างหรือหารด้วยศูนย์; สับสนระหว่างการคืนค่ากับการแสดงผล\n\nตัวอย่างผลลัพธ์: `{tests[0]['expected']!r}`"
            (ROOT/'explanations'/f'{eid}.md').write_text(explanation,encoding='utf-8')
            (ROOT/'hints').mkdir(exist_ok=True); (ROOT/'hints'/f'{eid}.json').write_text(json.dumps(ex['hints'],ensure_ascii=False,indent=2),encoding='utf-8')
            (ROOT/'tests').mkdir(exist_ok=True); (ROOT/'tests'/f'{eid}.json').write_text(json.dumps(tests,ensure_ascii=False,indent=2),encoding='utf-8')
    (ROOT/'curriculum.json').write_text(json.dumps(catalog,ensure_ascii=False,indent=2),encoding='utf-8')
    for level,(name,*_) in enumerate(LEVELS,1):
        (ROOT/'lessons').mkdir(exist_ok=True)
        (ROOT/'lessons'/f'level_{level:02d}.md').write_text(f'# Level {level:02d} — {name}\n\nแบบฝึกหัดระดับนี้ฝึกแนวคิดตามลำดับจากพื้นฐานไปสู่โจทย์ประยุกต์ ตรวจ prerequisite ก่อนทำแต่ละข้อ และใช้ `python practice.py lesson ID` เพื่อดูโจทย์กับตัวอย่าง\n',encoding='utf-8')
    print(f'Built {len(catalog)} exercises across {len(LEVELS)} levels')

if __name__=='__main__': build()
